ffect:o_bonus_2_4f5ddea253eb6dd100001f28fcdefa52"]={ ["PvE"]={ ["属性"]="暴击机率",["数值"]="15",["单位"]="%" },["PvP"]={ ["属性"]="暴击机率",["数值"]="8",["单位"]="%" } },["set:f58bdd5662d1630100036a5ebf371c3a#gear_effect:o_bonus_3_43a2c97052209a23000004db8af701b4"]={ ["PvE"]={ ["属性"]="装弹速度",["数值"]="30",["单位"]="%" },["PvP"]={ ["属性"]="装弹速度",["数值"]="30",["单位"]="%" } },["set:f58bdd5662d1630100036a5ebf371c3a#gear_effect:o_6cfec5e662cd8230000b2f8f77e16516"]={ ["PvE"]={ ["名称"]="弃暗\010\010投明",["图标"]="gear_effect:o_6cfec5e662cd8230000b2f8f77e16516",["描述"]="在掩体后时，每秒获得{{TD2文字|色=orange|文= 10 }}层叠加效果，最多可叠加至{{TD2文字|色=orange|文= 50 }}层。每叠加一层，爆击伤害都将提高{{TD2文字|色=orange|文= 1.2%}}，同时每分钟射速提高{{TD2文字|色=orange|文= 0.4%}}。\010\010\010\010从掩体后射击时，该增益不会生效。\010\010\010\010走出掩体后，玩家以正常速度移动时每秒失去{{TD2文字|色=orange|文= 2 }}层叠加效果，冲刺时每秒失去{{TD2文字|色=orange|文= 1 }}层叠加效果。\010\010\010\010在掩体外处于战斗状态时，每秒获得{{TD2文字|色=orange|文= 10 }}层叠加效果，最多可叠加至{{TD2文字|色=orange|文= 50 }}层。每一层效果被消耗时，都将回复玩家{{TD2文字|色=orange|文= 0.8% }}的装甲。\010\010只有在掩体后时，该叠加效果才会以每秒{{TD2文字|色=orange|文= 10 }}层的速度消耗。" },["PvP"]={ ["名称"]="弃暗\010\010投明",["图标"]="gear_effect:o_6cfec5e662cd8230000b2f8f77e16516",["描述"]="在掩体后时，每秒获得{{TD2文字|色=orange|文= 10 }}层叠加效果，最多可叠加至{{TD2文字|色=orange|文= 50 }}层。每叠加一层，爆击伤害都将提高{{TD2文字|色=orange|文= 0.5%}}，同时每分钟射速提高{{TD2文字|色=orange|文= 0.2%}}。\010\010\010\010从掩体后射击时，该增益不会生效。\010\010\010\010走出掩体后，玩家以正常速度移动时每秒失去{{TD2文字|色=orange|文= 2 }}层叠加效果，冲刺时每秒失去{{TD2文字|色=orange|文= 1 }}层叠加效果。\010\010\010\010在掩体外处于战斗状态时，每秒获得{{TD2文字|色=orange|文= 10 }}层叠加效果，最多可叠加至{{TD2文字|色=orange|文= 50 }}层。每一层效果被消耗时，都将回复玩家{{TD2文字|色=orange|文= 0.4% }}的装甲。\010\010只有在掩体后时，该叠加效果才会以每秒{{TD2文字|色=orange|文= 10 }}层的速度消耗。" } },["set:f58bdd5662d1630100036a5ebf371c3a#gear_effect:o_6cfec5e662d52202000913eb3048ed24"]={ ["PvE"]={ ["名称"]="弃暗",["图标"]="gear_effect:o_6cfec5e662d52202000913eb3048ed24",["描述"]="将“弃暗”的最大叠加层数从{{TD2文字|色=orange|文= 50 }}增加至{{TD2文字|色=orange|文= 100}}，每层增益从{{TD2文字|色=orange|文= 10 }}增加至{{TD2文字|色=orange|文= 20}}。" },["PvP"]={ ["名称"]="弃暗",["图标"]="gear_effect:o_6cfec5e662d52202000913eb3048ed24",[