0017fb77cdd48196",["描述"]="{{TD2文字|色=orange|文=充能时}}每秒获得 {{TD2文字|色=orange|文=12%}} 保护。" } },["exotic:3797e3755cf58f7000046e356c1e4d77#exotic_talent_3797e3755cf58568000446686cd74524"]={ ["PvE"]={ ["名称"]="超频转移",["图标"]="exotic_talent_3797e3755cf58568000446686cd74524",["描述"]="每上升一个技能分阶，就获得 {{TD2文字|色=orange|文=+15% 蜂窝技能加速}}。\010\010引爆蜂窝会重置技能冷却时间并获得{{TD2文字|色=orange|文=超载状态}}，持续 {{TD2文字|色=orange|文=15 秒}}。如果在技能分阶 6，此效果也会应用在所有友军身上。\010\010获得此效果的友军在 {{TD2文字|色=orange|文=120 秒}}内无法再度受益。" },["PvP"]={ ["名称"]="超频转移",["图标"]="exotic_talent_3797e3755cf58568000446686cd74524",["描述"]="引爆一个蜂窝会重置全部友军的技能冷却时间，并赋予他们{{TD2文字|色=orange|文= +6 技能分阶}}，持续 {{TD2文字|色=orange|文=15 秒}}。\010\010获得此效果的友军在 {{TD2文字|色=orange|文=120 秒}}内无法再度受益。" } },["exotic:4cdce5b25d5518e40003409a83b246b0#exotic_talent_0b88a6bc5de782990003a5d488d5ec75"]={ ["PvE"]={ ["名称"]="群体本能",["图标"]="exotic_talent_0b88a6bc5de782990003a5d488d5ec75",["描述"]="根据你与最后击中敌人的距离，你和所有友军都会获得对应的加成。\010\0100 至 15 米：{{TD2文字|色=orange|文=+25% 暴击伤害}}\01015 至 25 米：{{TD2文字|色=orange|文=+10% 暴击伤害}}并 {{TD2文字|色=orange|文=+10% 暴击机率}}\01025 米以上：{{TD2文字|色=orange|文=+25% 暴击机率}}" },["PvP"]={ ["名称"]="群体本能",["图标"]="exotic_talent_0b88a6bc5de782990003a5d488d5ec75",["描述"]="根据你与最后击中敌人的距离，你和所有友军都会获得对应的加成。\010\0100 至 15 米：{{TD2文字|色=orange|文=+18% 暴击伤害}}\01015 至 25 米：{{TD2文字|色=orange|文=+8% 暴击伤害}}并 {{TD2文字|色=orange|文=+8% 暴击机率}}\01025 米以上：{{TD2文字|色=orange|文=+18% 暴击机率}}" } },["exotic:4cdce5b25d5518350003408f5eb82b7d#exotic_talent_0b88a6bc5ddfc57700035d421edcad9a"]={ ["PvE"]={ ["名称"]="隔离纳米镀层",["图标"]="exotic_talent_0b88a6bc5ddfc57700035d421edcad9a",["描述"]="当你或任何友军的装甲遭到破坏时，你 {{TD2文字|色=orange|文=80%}} 的装甲将作为他们的{{TD2文字|色=orange|文=加成装甲}}，持续 {{TD2文字|色=orange|文=10 秒}}。\010\010每位友军的冷却时间：{{TD2文字|色=orange|文=45 秒}}\010\010使用你的专长武器击杀一名敌人可消除所有友军的冷却时间。" },["PvP"]={ ["名称"]="隔离纳米镀层",["图标"]="exotic_talent_0b88a6bc5ddfc57700035d421edcad9a",["描述"]="当你或任何友军的装甲遭到破坏时，你 {{TD2文字|色=orange|文=30%}} 的装甲将作为他们的{{TD2文字|色=orange|文=加成装甲}}，持续 {{TD2文字|色=orange|文=5 秒}}。\010\010每位友军的冷却时间：{{TD2文字|色=orange|文=30 秒}}\010\010使用你的专长武器