f5f9f7e77e"]={ ["PvE"]={ ["名称"]="坚守阵地",["图标"]="exotic_talent_32d246155c900e15000327f5f9f7e77e",["描述"]="不会被爆炸所吓阻。\010\010未移动的每一秒都会提升总{{TD2文字|色=orange|文=武器伤害}} {{TD2文字|色=orange|文=3%}}。直到你开始移动前可叠加至 {{TD2文字|色=orange|文=10}}。开始移动 {{TD2文字|色=orange|文=10秒}} 后，所有叠加将会归零。" },["PvP"]={ ["名称"]="坚守阵地",["图标"]="exotic_talent_32d246155c900e15000327f5f9f7e77e",["描述"]="不会被爆炸所吓阻。\010\010未移动的每一秒都会提升总{{TD2文字|色=orange|文=武器伤害}} {{TD2文字|色=orange|文=3%}}。直到你开始移动前可叠加至 {{TD2文字|色=orange|文=10}}。开始移动 {{TD2文字|色=orange|文=10秒}} 后，所有叠加将会归零。" } },["exotic:b00501356a8fe4a800037e6abdc9d3ab#exotic_talent_04b83df56a9028560003da7d55b857e6"]={ ["PvE"]={ ["名称"]="诱饵之王",["图标"]="exotic_talent_04b83df56a9028560003da7d55b857e6",["描述"]="在战斗中，月相每过{{TD2文字|色=orange|文= 5 秒}}便会发生变化。共有 8 种月相。\010\010从{{TD2文字|色=orange|文=新月}}开始，你造成的所有伤害会提升{{TD2文字|色=orange|文= 5%}}。每个月相都会使提升量增加{{TD2文字|色=orange|文= 5%}}，最终在{{TD2文字|色=orange|文=满月}}时达到{{TD2文字|色=orange|文=25%}}，随后在月亮回归{{TD2文字|色=orange|文=新月}}的期间降低，完成一个循环。\010\010在{{TD2文字|色=orange|文=满月}}期间，部署{{TD2文字|色=orange|文=诱饵}}会使其获得{{TD2文字|色=orange|文=超载}}效果，且循环会{{TD2文字|色=orange|文=暂停 10 秒}}。" },["PvP"]={ ["名称"]="诱饵之王",["图标"]="exotic_talent_04b83df56a9028560003da7d55b857e6",["描述"]="在战斗中，月相每过{{TD2文字|色=orange|文= 3 秒}}便会发生变化。共有 8 种月相。\010\010从{{TD2文字|色=orange|文=新月}}开始，你造成的所有伤害会提升{{TD2文字|色=orange|文= 6%}}。每个月相都会使提升量增加{{TD2文字|色=orange|文= 6%}}，最终在{{TD2文字|色=orange|文=满月}}时达到{{TD2文字|色=orange|文=20%}}，随后在月亮回归{{TD2文字|色=orange|文=新月}}的期间降低，完成一个循环。\010\010在{{TD2文字|色=orange|文=满月}}期间，部署{{TD2文字|色=orange|文=诱饵}}会使其获得{{TD2文字|色=orange|文=超载}}效果，且循环会{{TD2文字|色=orange|文=暂停 8 秒}}。" } },["exotic:346395bc5eff309f0003a7d41bab9c36#exotic_talent_346395bc5eff32b00003ab84932b6fb5"]={ ["PvE"]={ ["名称"]="已确认击杀",["图标"]="exotic_talent_346395bc5eff32b00003ab84932b6fb5",["描述"]="你所击杀的敌人会在死亡时掉落一个挂饰。收集挂饰会给予或长或短的增益，第一个增益由装备的核心属性数量而定，并且持续 {{TD2文字|色=orange|文=10 秒}}。\010\010{{TD2图标|类别=state|键=red}} - {{TD2文字|色=orange|文=+5%}} 武器伤害\010{{TD2图标|类别=state|键=blue}} - {{TD2文字|色=orange|文=+10%}} 加成装甲\010{{TD2图标|类别=state|键=yellow}} - {{TD2文字|色=orange|文=+5%}} 技能效率\010\010每收集到一个挂饰，就可以获得额外 {{TD2文字|色=orange|文=+1%}} 武器伤害、{{TD2文字|色=orange|文=+1%}} 技能效率以及 {{TD2文字|色=orange|文=+0.1%}} 装甲回复，持续 {{TD2文字|色=orange|文=300 秒}}。\010\010最多叠加 {{TD2文字|色=orange|文=30}} 次。" },["PvP"]={ ["名称"]="已确认击杀",["图标"]="exotic_talent_346395bc5eff32b00003ab84932b6fb5",["描述"]="你所击杀的敌人会在死亡时掉落一个挂饰。收集挂饰会给予或长或短的增益，第一个增益由装备的核心属性数量而定，并且持续 {{TD2文字|色=orange|文=8 秒}}。\010\010{{TD2图标|类别=state|键=red}} - {{TD2文字|色=orange|文=+4%}} 武器伤害\010{{TD2图标|类别=state|键=blue}} - {{TD2文字|色=orange|文=+6%}} 加成装甲\010{{TD2图标|类别=state|键=yellow}} - {{TD2文字|色=orange|文=+2%}} 技能效率\010\010每收集到一个挂饰，就可以获得额外 {{TD2文字|色=orange|文=+1%}} 武器伤害、{{TD2文字|色=orange|文=+1%}} 技能效率以及 {{TD2文字|色=orange|文=+0.1%}} 装甲回复，持续 {{TD2文字|色=orange|文=120 秒}}。\010\010最多叠加 {{TD2文字|色=orange|文=15}} 次。" } },["exotic:3797e3755cd19a8600033254284fcdb7#exotic_talent_3797e3755cbf595900041283daed5671"]={ ["PvE"]={ ["名称"]="快速拔枪",["图标"]="exotic_talent_3797e3755cbf595900041283daed5671",["描述"]="当手枪收起时，每 {{TD2文字|色=orange|文=0.3 秒}}都会获得叠加的增益效果，最多叠加至 {{TD2文字|色=orange|文=100}} 次。\010\010切换至手枪时，你所发射的第一枪会消耗增益效果，每层可造成 {{TD2文字|色=orange|文=+10% 的伤害}}。此将对被你打中者造成爆头伤害。" },["PvP"]={ ["名称"]="快速拔枪",["图标"]="exotic_talent_3797e3755cbf595900041283daed5671",["描述"]="当手枪收起时，每 {{TD2文字|色=orange|文=1 秒}}都会获得叠加的增益效果，最多叠加至 {{TD2文字|色=orange|文=36}} 次。\010\010切换至手枪时，你所发射的第一枪会消耗增益效果，每层可造成 {{TD2文字|色=orange|文=+1% 的伤害}}。此将对被你打中者造成爆头伤害。" } },["exotic:b00501356a70059d0006f6608bf523ea#exotic_talent_19373b006a5f73b200037c841656c534"]={ ["PvE"]={ ["名称"]="决定一击",["图标"]="exotic_talent_19373b006a5f73b200037c841656c534",["描述"]="下次{{TD2文字|色=orange|文=命中身躯}}的攻击会被视作{{TD2文字|色=orange|文=爆头}}。\010\010冷却时间：{{TD2文字|色=orange|文=2 秒}}" },["PvP"]={ ["名称"]="决定一击",["图标"]="exotic_talent_19373b006a5f73b200037c841656c534",["描述"]="下次{{TD2文字|色=orange|文=命中身躯}}的攻击会被视作{{TD2文字|色=orange|文=爆头}}。（在 PvP 环境中，此效果对射手步枪无效）\010\010冷却时间：{{TD2文字|色=orange|文=6 秒}}" } },["exotic:4cdce5b25be1b0b000032b512386d5e7#exotic_talent_0b88a6bc5ddd22960033efc284ccb7f7"]={ ["PvE"]={ ["名称"]="一个在手……",["图标"]="exotic_talent_0b88a6bc5ddd22960033efc284ccb7f7",["描述"]="投掷的手雷会返还并可获得 {{TD2文字|色=orange|文=+1 技能分阶}}，持续 {{TD2文字|色=orange|文=15 秒}}。若技能分阶已为 6，则可获得{{TD2文字|色=orange|文=超载}}效果。\010\010冷却时间：{{TD2文字|色=orange|文=60 秒}}" },["PvP"]={ ["名称"]="一个在手……",["图标"]="exotic_talent_0b88a6bc5ddd22960033efc284ccb7f7",["描述"]="投掷的手雷会返还并可获得 {{TD2文字|色=orange|文=+1 技能分阶}}，持续 {{TD2文字|色=orange|文=10 秒}}。\010\010冷却时间：{{TD2文字|色=orange|文=60 秒}}" } },["exotic:4cdce5b25be1b0b000032b512386d5e7#exotic_talent_0b88a6bc5ddd2159002e9a26ab520070"]={ ["PvE"]={ ["名称"]="……两个在包",["图标"]="exotic_talent_0b88a6bc5ddd2159002e9a26ab520070",["描述"]="{{TD2文字|色=orange|文=装甲包容量 +1}}\010{{TD2文字|色=orange|文=手雷容量 +3}}\010{{TD2文字|色=orange|文=弹药容量 +25%}}\010{{TD2文字|色=orange|文=修复技能 +10%}}\010{{TD2文字|色=orange|文=状态效果 +10%}}" },["PvP"]={ ["名称"]="……两个在包",["图标"]="exotic_talent_0b88a6bc5ddd2159002e9a26ab520070",["描述"]="{{TD2文字|色=orange|文=装甲包容量 +2}}\010{{TD2文字|色=orange|文=手雷容量 +3}}\010{{TD2文字|色=orange|文=弹药容量 +20%}}\010{{TD2文字|色=orange|文=修复技能 +10%}}\010{{TD2文字|色=orange|文=状态效果 +6%}}" } },["exotic:b005013565e83fa600079a2bca93353e#exotic_talent_c487423d660a9b8f000533725f1e1594"]={ ["PvE"]={ ["名称"]="逃生计划",["图标"]="exotic_talent_c487423d660a9b8f000533725f1e1594",["描述"]="{{TD2文字|色=orange|文=+20% 移动速度}}" },["PvP"]={ ["名称"]="逃生计划",["图标"]="exotic_talent_c487423d660a9b8f000533725f1e1594",["描述"]="{{TD2文字|色=orange|文=+6% 移动速度}}" } },["exotic:b005013568ee1608002429906813a622#exotic_talent_a2264a1668ee337d0003bfce09d46322"]={ ["PvE"]={ ["名称"]="驱逐",["图标"]="exotic_talent_a2264a1668ee337d0003bfce09d46322",["描述"]="命中敌人后会施加一个标记。标记只能同时存在一个，且会在{{TD2文字|色=orange|文= 15 秒}}后，或被标记敌人死亡后消失。\010从被标记的敌人处获得 {{TD2文字|色=orange|文=600% 伤害增益}}。\010对未标记敌人造成 {{TD2文字|色=orange|文=30% 额外伤害}}。\010如果在战斗中只剩下一名敌人，则标记消失且无法再次施加。" },["PvP"]={ ["名称"]="驱逐",["图标"]="exotic_talent_a2264a1668ee337d0003bfce09d46322",["描述"]="命中敌人后会施加一个标记。标记只能同时存在一个，且会在{{TD2文字|色=orange|文= 4 秒}}后，或被标记敌人死亡后消失。\010从被标记的敌人处获得 {{TD2文字|色=orange|文=220% 伤害增益}}。\010对未标记敌人造成 {{TD2文字|色=orange|文=22% 额外伤害}}。\010如果在战斗中只剩下一名敌人，则标记消失且无法再次施加。" } },["set:b00501356a9699cc000